/opt/homebrew/bin/zsh -lc "python3 -c 'import sqlite3,json; p=\"poc/data/clean-carried-run-2026-11-16/slice/trace.sqlite\"; c=sqlite3.connect(\"file:\"+p+\"?mode=ro\",uri=True); r=c.execute(\"select manifest,initial_theses from run\").fetchone(); rows=c.execute(\"select sequence,input_id,status,result,before_state,after_state from trace order by sequence\").fetchall(); print(\"manifest\",len(json.loads(r[0])[\"item_ids\"]),\"trace\",len(rows),\"statuses\",{x[2]:sum(z[2]==x[2] for z in rows) for x in rows}); opens=[]; ev=0; no=0; homes={};
for s,i,st,res,b,a in rows:
 if st"'!="complete": continue
 before={t["id"] for t in json.loads(b)}; after=json.loads(a); opens += [(s,t["description"]) for t in after if t["id"] not in before]; data=json.loads(res); ev+=len(data["evidence"]); no+=sum(not x["links"] for x in data["evidence"])
print("opened",opens,"evidence",ev,"empty links",no)'"'"

